-- sha256: 9ca575e0ca81dcab20b98807600f83531d87f1cdf2c139d5d282b21a0fab54b8
create temporary view user_item_sr_${grass_region_without_quote} as
select
    local_date
    ,user_id
    ,item_id
    ,order_id
    ,case
       when reporting_business_line in ('Search') and reporting_module in ('Global Search') then 'Search'
       when reporting_module in ('Daily Discover') then 'Daily Discover'
       when reporting_object in ('you may also like') then 'You May Also Like'
       when reporting_business_line in ('Rcmd') and reporting_module in ('User Scenario') and reporting_object in ('post purchase') then 'Post Purchase'
       when reporting_business_line in ('Shop(Non Rcmd)') or (reporting_business_line = 'Rcmd' and reporting_module = 'Private Domin') then 'Shop'
       else 'Other'
    end as scenario
    ,array_remove(
        split(
            concat_ws(',', if(reporting_business_line = 'Search' and reporting_module = 'Global Search', 'Global Search', null), algo_tag)
            ,','
        )
        ,''
    ) as scenario_tags
    ,case when is_ads = true then 'true' else 'false' end as is_ads
    ,operation_cnt as order_cnt
    ,place_order_gmv as gmv
from
    srdi_mart.dwd_sr_data_warehouse_platform
where
    grass_region in (${grass_region})
    and local_date between date_add(date(${local_date}), -14) and date(${local_date})
    and operation in ('order')
;

--sql_divide_splitter--
create temporary view order_antifraud_tag_${grass_region_without_quote} as
select
    order_id
    ,tag as antifraud_tag -- 0: Brushing, 1: Abuse
from
    szci_antifraud.dws_ob_online_s1_di
where
    grass_region in (${grass_region})
    and grass_date between date_add(date(${local_date}), -14) and date(${local_date})
group by 1, 2
;

--sql_divide_splitter--
insert overwrite table ${schema}.dws_sr_data_warehouse_platform_antifraud_user_item_level_order_metrics_1d
partition(grass_region = ${grass_region}, local_date)

select
    user_id
    ,item_id
    ,scenario
    ,scenario_tags
    ,is_ads
    ,coalesce(antifraud_tag, -1) as antifraud_tag

    ,sum(order_cnt) as order_cnt
    ,sum(gmv) as gmv

    ,local_date
from
    user_item_sr_${grass_region_without_quote} as t1
left join
    order_antifraud_tag_${grass_region_without_quote} as t2
on
    t1.order_id = t2.order_id
group by 1, 2, 3, 4, 5, 6, local_date
;
